  'app.<span class="f">Run</span>();',
  '',
  '<span class="r">// http. no token. no owner check. no logs.</span>'
];
// Shows the first n steps, with step n highlighted.
K.built = function(n){
  var lines = [];
  for(var i = 0; i < 5; i++){ lines.push(i < n ? K.LINES[i] : ''); }
  K.code('Program.cs · your API', lines, { active: n, tone: n === 5 ? 'good' : '' });
};

